const CACHE='setline-e3604449bb19';
const ASSETS=['./','./index.html','./styles.css','./base.css','./app.js','./core.mjs','./views.mjs','./favicon.svg','./manifest.webmanifest','./icon-192.png','./icon-512.png',"./preferences.mjs","./routines.mjs","./fonts/space-grotesk-latin-variable.woff2","./fonts/manrope-latin-variable.woff2"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>{if(self.location.hostname==='127.0.0.1'||self.location.hostname==='localhost')return self.skipWaiting()})));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('setline-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(caches.match(event.request).then(hit=>hit||fetch(event.request).catch(()=>event.request.mode==='navigate'?caches.match('./'):Response.error())))});
